Define
\[
\hat{\omega}^{\mathrm{univ}}:=\sqrt{-1}\partial \overline{\partial} \left( 2 (\mathrm{Im}w)^{\!^{\intercal}} (\mathrm{Im} Z)^{-1} (\mathrm{Im}w) \right).
\]
Then $\hat{\omega}^{\mathrm{univ}}$ is a closed  semi-positive
$(1,1)$-form on $\IC^g\times\mathfrak{H}_g$ satisfying 
\begin{equation}
  \label{eq:bettiformaltformula}

  \hat{\omega}^{\mathrm{univ}} = \sqrt{-1} \tran{\left( \rmd Z \Y^{-1}
      \mathrm{Im}(w) - \rmd w\right)} \wedge \Y^{-1} \left( \rmd \overline Z \Y^{-1}
    \mathrm{Im}(w) - \rmd \overline w\right)
\end{equation}
with $\Y = \mathrm{Im}(Z)$; here and below the symbol $\wedge$
is used as a combination of wedge product and matrix multiplication
when appropriate. 
Moreover, if $N\in\IZ$ and if we denote by $\widetilde{N} \colon \IC^g \times \mathfrak{H}_g \rightarrow \IC^g \times \mathfrak{H}_g$ the map $(w,Z) \mapsto (Nw,Z)$, then $\widetilde{N}^*\hat{\omega}^{\mathrm{univ}} = N^2\hat{\omega}^{\mathrm{univ}}$.

Assume $\cA \rightarrow S$ is $\mathfrak{A}_g \rightarrow \mathbb A_g$. Let $X$ be an irreducible subvariety of $\mathfrak{A}_g$ of dimension
$d$ and let $\Delta$ be an open subset of $\an{S}$ with $\sman{X}\cap\cA_\Delta\not=\emptyset$. Then
\begin{equation}
\label{prop:bettformvsrankuniv}

 \omega^{\mathrm{univ}}|_{\sman{X}}^{\wedge d} \not\equiv 0
\quad\text{if and only if}\quad
\max_{x \in \sman{X}\cap\cA_\Delta} \mathrm{rank}_{\IR} (\mathrm{d}b_\Delta|_{\sman{X}})_{x} = 2d.
\end{equation}

Let $b_{\Delta} \colon \cA_{\Delta} \rightarrow \mathbb T^{2g}$ be a Betti map as in Proposition~\ref{PropBettiMapApp}. 
Let $X$ be an irreducible subvariety of $\cA$ with $\an{X}\cap\cA_\Delta\not=\emptyset$. Let $U$ be a Zariski open dense subset of $X$. Then
\begin{equation}\label{EqBettiRankSmallerUnderRestriction}

\max_{x \in X^{\mathrm{sm}}(\IC) \cap \cA_{\Delta}} \mathrm{rank}_{\IR} (\mathrm{d}b_{\Delta}|_{X^{\mathrm{sm,an}}})_x = \max_{u \in U^{\mathrm{sm}}(\IC) \cap \cA_{\Delta}} \mathrm{rank}_{\IR} (\mathrm{d}b_{\Delta}|_{U^{\mathrm{sm,an}}})_u.
\end{equation}

Assume $d \ge 1$.  There exists a constant $c>0$ depending on the data introduced above
  with the following property. Say $N\ge 1$ is a power of $2$, then
  \begin{equation*}
    (\cM\cdot \cF^{\cdot(d-1)}) \le c N^{2(d-1)}.
  \end{equation*}

Let $g \ge 2$ and $d \ge 1$ be integers. Then there exists a constant
  $c = c(g, d) \ge 1$ with the following property. If $C$ is a smooth curve
  of genus $g$  defined
  over a number field $F$  with $[F:\IQ] \le d$, then
  \begin{equation}
    \label{eq:CKexpinrank}

      \#C(F) \le c^{1+\rho}
  \end{equation}
  where $\rho$ is the rank of  $\mathrm{Jac}(C)(F)$.

Suppose that $\cA$ and $S$ are as above with $k=\IQbar$;
  in particular, $\cA$ satisfies {\tt (Hyp)}.
  Let $X$ be a closed irreducible subvariety of $\cA$
  defined over $\IQbar$ that dominates $S$.   Suppose $X$ is non-degenerate,
  as defined in Definition~\ref{DefinitionNonDegenerate}. Then there
  exist constants $c_1>0$ and $c_2\ge 0$ and a Zariski open dense subset
  $U$ of $X$ with 
  \begin{equation*}
    \hat{h}_{\cA}(P) \ge c_1 h( \pi(P) ) - c_2 \quad \text{for all}\quad P \in U(\IQbar).
  \end{equation*}
